            },
            "image": {
              "$ref": "#/definitions/image"
            },
            "max-time": {
              "$ref": "#/definitions/max_time"
            },
            "name": {
              "type": "string",
              "description": "Name of the step",
              "minLength": 1
            },
            "oidc": {
              "type": "boolean",
              "description": "Enable the use of OpenID Connect to connect a pipeline step to a resource server"
            },
            "runs-on": {
              "oneOf": [
                {
                  "$ref": "#/definitions/runner_label"
                },
                {
