            },
            "services": {
              "type": "array",
              "description": "Services enabled for the step",
              "items": {
                "type": "string",
                "description": "Name of the service"
              },
              "minItems": 1,
              "maxItems": 5
            },
            "size": {
              "$ref": "#/definitions/size"
            },
            "trigger": {
              "$ref": "#/definitions/trigger",
              "description": "Specifies if a step runs automatically or only when manually triggered by a user"
            }
          },
          "required": [
            "script"
          ]
        }
      },
      "additionalProperties": false
    },
    "stage": {
      "type": "object",
      "properties": {
        "stage": {
          "type": "object",
          "properties": {
            "condition": {
              "$ref": "#/definitions/condition",
              "description": "Condition to execute the stage"
            },
            "deployment": {
              "type": "string",
              "description": "Type of environment for the deployment stage, used in the Deployments dashboard",
              "minLength": 1
            },
            "name": {
              "type": "string",
              "description": "Name of the stage",
              "minLength": 1
            },
            "steps": {
              "type": "array",
              "description": "List of steps in a stage",
              "items": {
                "$ref": "#/definitions/step"
              },
              "minItems": 1
            },
            "trigger": {
              "$ref": "#/definitions/trigger",
              "description": "Specifies if the stage runs automatically or only when manually triggered by a user"
            }
          },
          "required": [
            "steps"
          ],
          "additionalProperties": false
        }
      },
      "additionalProperties": false
    },
    "parallel_steps": {
      "type": "array",
      "description": "Set of steps to run concurrently",
      "items": {
        "$ref": "#/definitions/step"
      },
      "minItems": 2
    },
    "step_or_stage_or_parallel_item": {
      "oneOf": [
        {
          "$ref": "#/definitions/step"
        },
        {
          "$ref": "#/definitions/stage"
        },
        {
          "type": "object",
          "properties": {
            "parallel": {
              "oneOf": [
                {
                  "$ref": "#/definitions/parallel_steps"
                },
                {
                  "type": "object",
                  "properties": {
                    "fail-fast": {
                      "$ref": "#/definitions/fail_fast",
                      "description": "A flag reflecting whether all steps in a parallel group should be force stopped if any of its steps fails."
                    },
                    "steps": {
                      "$ref": "#/definitions/parallel_steps"
                    }
                  },
                  "required": [
                    "steps"
                  ],
                  "additionalProperties": false
                }
              ]
            }
          },
          "additionalProperties": false
        }
      ]
    },
    "actions_list": {
      "type": "array",
      "items": {
        "$ref": "#/definitions/step_or_stage_or_parallel_item"
      },
      "minItems": 1
    },
    "named_pipelines": {
      "type": "object",
      "patternProperties": {
        "^.*$": {
          "$ref": "#/definitions/actions_list"
        }
      }
    },
    "script": {
      "type": "array",
      "items": {
        "oneOf": [
          {
            "type": "string",
            "description": "Command to execute"
          },
          {
            "$ref": "#/definitions/pipe"
          }
        ]
      },
      "minItems": 1
    },
    "pipe": {
      "type": "object",
      "description": "Pipe to execute",
      "properties": {
        "pipe": {
          "type": "string",
          "description": "Pipe identifier"
        },
        "variables": {
          "type": "object",
          "description": "Environment variables passed to the pipe",
          "patternProperties": {
            "^.*$": {
              "oneOf": [
                {
                  "type": "string",
                  "description": "Variable value"
                },
                {
                  "type": "array",
                  "items": {
                    "type": "string",
                    "description": "Array variable item value"
                  },
                  "minItems": 1
                }
              ]
            }
          },
          "minProperties": 1
        }
      },
      "required": [
        "pipe"
      ]
    },
    "cache_path": {
      "type": "string",
      "description": "Path to the directory to be cached, can be absolute or relative to the clone directory"
    },
    "cache_with_key": {
      "type": "object",
      "description": "Cache definition declaring a set of files as a key and path to the directory to be cached",
      "properties": {
        "key": {
          "type": "object",
          "description": "Cache key definition",
          "properties": {
            "files": {
              "type": "array",
              "items": {
                "type": "string",
                "description": "Path to a file or glob pattern of files in the repository which form the cache key"
              },
              "minItems": 1
            }
          },
          "required": [
            "files"
          ],
          "additionalProperties": false
        },
        "path": {
          "$ref": "#/definitions/cache_path"
        }
      },
      "required": [
        "key",
        "path"
      ],
      "additionalProperties": false
    }
  },
  "type": "object",
  "properties": {
    "clone": {
      "$ref": "#/definitions/clone_properties"
    },
    "definitions": {
      "type": "object",
      "description": "Defines resources used elsewhere in the pipeline configuration",
      "properties": {
        "caches": {
          "type": "object",
          "description": "Defines custom caches to be used by pipelines",
          "patternProperties": {
            "^[a-z0-9]([-a-z0-9]{0,48}[a-z0-9])?$": {
              "oneOf": [
                {
                  "$ref": "#/definitions/cache_path"
                },
                {
                  "$ref": "#/definitions/cache_with_key"
                }
              ]
            }
          },
          "not": {
            "required": [
              "docker"
            ]
          },
          "additionalProperties": false
        },
        "services": {
          "type": "object",
          "description": "Defines services that run in separate Docker containers",
          "patternProperties": {
            "^.*$": {
              "type": "object",
              "properties": {
                "image": {
                  "$ref": "#/definitions/image"
                },
                "memory": {
                  "type": "number",
                  "description": "Memory limit for the service container, in megabytes",
                  "minimum": 128,
                  "default": 1024
                },
                "variables": {
                  "type": "object",
                  "description": "Environment variables passed to the service container",
                  "patternProperties": {
                    "^.*$": {
                      "type": "string"
                    }
                  },
                  "minProperties": 1
                }
              }
            }
          },
          "additionalProperties": false
        }
      }
    },
    "image": {
      "$ref": "#/definitions/image"
    },
    "options": {
      "type": "object",
      "properties": {
        "docker": {
          "type": "boolean",
          "description": "A flag to add Docker to all build steps in all pipelines"
        },
        "max-time": {
          "$ref": "#/definitions/max_time"
        },
        "size": {
          "$ref": "#/definitions/size"
        }
      }
    },
    "pipelines": {
      "type": "object",
      "properties": {
        "default": {
          "$ref": "#/definitions/actions_list"
        },
        "branches": {
          "$ref": "#/definitions/named_pipelines",
          "description": "Branch-specific build pipelines"
        },
        "custom": {
          "type": "object",
          "description": "Pipelines that can only be triggered manually or scheduled from the Bitbucket Cloud interface",
          "patternProperties": {
            "^.*$": {
              "type": "array",
              "items": {
                "oneOf": [
                  {
                    "type": "object",
                    "properties": {
                      "variables": {
                        "type": "array",
                        "description": "List of variables for the custom pipeline",
                        "items": {
                          "type": "object",
                          "properties": {
                            "name": {
                              "type": "string",
                              "description": "Name of a variable for the custom pipeline",
                              "minLength": 1
                            },
                            "default": {
                              "type": "string",
                              "description": "Default value for the variable, used unless the value is manually set when the pipeline is run"
                            },
                            "allowed-values": {
                              "type": "array",
                              "description": "A list of values that are allowed for the variable",
                              "items": {
                                "type": "string",
                                "description": "Allowed value for the variable"
                              },
                              "minItems": 1
                            },
                            "description": {
                              "type": "string",
                              "description": "Description of the variable",
                              "minLength": 1
                            }
                          },
                          "required": [
                            "name"
                          ],
                          "additionalProperties": false
                        },
                        "minItems": 1
                      }
                    },
                    "additionalProperties": false
                  },
                  {
                    "$ref": "#/definitions/step_or_stage_or_parallel_item"
                  }
                ]
              },
              "minItems": 1
            }
          }
        },
        "pull-requests": {
          "$ref": "#/definitions/named_pipelines",
          "description": "Pull-request-specific build pipelines"
        },
        "tags": {
          "$ref": "#/definitions/named_pipelines",
          "description": "Tag-specific build pipelines"
        }
      },
      "additionalProperties": false
    }
  },
  "required": [
    "pipelines"
  ]
}

{
  "$id": "https://json.schemastore.org/bukkit-plugin",
  "$schema": "http://json-schema.org/draft-07/schema#",
  "additionalProperties": true,
  "definitions": {
    "plugin-name": {
      "type": "string",
      "pattern": "^[A-Za-z0-9_\\.-]+$"
    },
    "command": {
      "description": "Optional command attributes.",
      "type": "object",
      "properties": {
        "description": {
          "description": "A user-friendly description for a command.",
          "type": "string"
        },
        "aliases": {
          "description": "Alternate command names a user may use instead.",
          "type": ["string", "array"]
        },
        "permission": {
          "description": "The permission required to use the command.",
          "type": "string"
        },
        "permission-message": {
          "description": "A no-permission message.",
          "type": "string",
          "examples": ["You do not have <permission>"]
        },
        "usage": {
          "description": "A short description of how to use this command.",
          "type": "string"
        }
      }
    },
    "permission": {
      "description": "Optional permission attributes.",
      "properties": {
        "description": {
          "description": "A short description of what this permission allows.",
          "type": "string"
        },
        "default": {
          "description": "The default state for the permission.",
          "$ref": "#/definitions/default-permission"
        },
        "children": {
          "description": "Allows other permissions to be set as a relation to the parent permission.",
          "type": ["array", "object"],
          "items": {
            "type": "string"
          },
          "additionalProperties": {
            "type": ["boolean", "object"],
            "items": {
              "type": "boolean"
            },
            "$ref": "#/definitions/permission"
          }
        }
      }
    },
    "default-permission": {
      "type": ["string", "boolean"],
      "enum": [true, false, "op", "not op"],
      "default": "op"
    }
  },
  "properties": {
    "name": {
      "description": "The unique name of plugin.",
      "$ref": "#/definitions/plugin-name"
    },
    "main": {
      "description": "The plugin's initial class file.",
      "type": "string",
      "pattern": "^(?!org\\.bukkit\\.)([a-zA-Z_$][a-zA-Z\\d_$]*\\.)*[a-zA-Z_$][a-zA-Z\\d_$]*$"
    },
    "version": {
      "description": "A plugin revision identifier.",
      "type": ["string", "number"]
    },
    "description": {
      "description": "Human readable plugin summary.",
      "type": "string"
    },
    "author": {
      "description": "The plugin author.",
      "type": "string"
    },
    "authors": {
      "description": "The plugin contributors.",
      "type": "array",
      "items": {
        "type": "string"
      }
    },
    "website": {
      "title": "Website",
      "description": "The URL to the plugin's site",
      "type": "string",
      "format": "uri"
    },
    "prefix": {
      "description": "The token to prefix plugin log entries.",
      "type": "string"
    },
    "database": {
      "description": "Set to true if this plugin uses a database.",
      "type": "boolean",
      "default": false
    },
    "load": {
      "description": "The phase of server-startup this plugin will load during.",
      "type": "string",
      "enum": ["STARTUP", "POSTWORLD"],
      "default": "POSTWORLD"
    },
    "depend": {
      "description": "Other required plugins.",
      "type": "array",
      "items": {
        "$ref": "#/definitions/plugin-name"
      }
    },
    "softdepend": {
      "description": "Other plugins that add functionality.",
      "type": "array",
      "items": {
        "$ref": "#/definitions/plugin-name"
      }
    },
    "loadbefore": {
      "description": "A list of plugins should be loaded after this plugin.",
      "type": "array",
      "items": {
        "$ref": "#/definitions/plugin-name"
      }
    },
    "commands": {
      "description": "The commands the plugin will register",
      "type": "object",
      "additionalProperties": {
        "$ref": "#/definitions/command"
      }
    },
    "permissions": {
      "description": "The permissions the plugin will register",
      "type": "object",
      "additionalProperties": {
        "type": "object",
        "$ref": "#/definitions/permission"
      }
    },
    "default-permission": {
      "description": "Gives the default default state of permissions registered for the plugin.",
      "$ref": "#/definitions/default-permission"
    },
    "awareness": {
      "description": "The concepts that the plugin acknowledges.",
      "type": "array",
      "items": {
        "type": "string",
        "pattern": "^!@.+$",
        "examples": ["!@UTF-8"]
      }
    },
    "api-version": {
      "description": "Gives the API version which this plugin is designed to support.",
      "type": ["string", "number"],
      "examples": ["1.13", "1.14", "1.15", "1.16"]
    },
    "libraries": {
      "description": "A list of libraries the server should download and supply to the plugin when loading it.",
      "type": "array",
      "items": {
        "type": "string",
        "description": "A single server provided library. This library can be used during runtime without being shaded into the plugin jar.",
        "pattern": "([^: ]+):([^: ]+)(:([^: ]*)(:([^: ]+))?)?:([^: ]+)",
        "examples": [
          "org.xerial:sqlite-jdbc:3.34.0",
          "com.google.dagger:dagger:2.36"
        ]
      }
    }
  },
  "required": ["name", "main", "version"],
  "title": "JSON schema for Bukkit Plugin YAML",
  "type": "object"
}

{
  "$schema": "http://json-schema.org/draft-04/schema#",
  "id": "https://json.schemastore.org/jshintrc",
  "properties": {
    "bitwise": {
      "description": "Prohibit the use of bitwise operators (&, |, ^, etc.)",
      "type": "boolean",
      "default": false
    },
    "curly": {
      "description": "Requires you to always put curly braces around blocks in loops and conditionals",
      "type": "boolean",
      "default": false
    },
    "eqeqeq": {
      "description": "Prohibits the use of `==` and `!=` in favor of `===` and `!==`",
      "type": "boolean",
      "default": false
    },
    "esversion": {
      "description": "The ECMAScript version to which the code must adhere",
      "type": "integer",
      "default": 5,
      "enum": [3, 5, 6, 7, 8, 9, 10, 11]
    },
    "forin": {
      "description": "Requires all `for in` loops to filter object's items with obj.hasOwnProperty()",
      "type": "boolean",
      "default": false
    },
    "freeze": {
      "description": "Prohibits overwriting prototypes of native objects such as Array, Date and so on",
      "type": "boolean",
      "default": false
    },
    "funcscope": {
      "description": "Suppresses warnings about declaring variables inside of control structures while accessing them later from the outside",
      "type": "boolean",
      "default": false
    },
    "futurehostile": {
      "description": "Enables warnings about the use of identifiers which are defined in future versions of JavaScript",
      "type": "boolean",
      "default": false
    },
    "iterator": {
      "description": "Suppresses warnings about the __iterator__ property.",
      "type": "boolean",
      "default": false
    },
    "latedef": {
