        {
          "$ref": "#/definitions/base"
        }
      ]
    },
    "prefer_english_operator": {
      "description": "This rule prohibits `&&`, `||`, `==`, `!=` and `!`. Use `and`, `or`, `is`, `isnt`, and `not` instead. `!!` (for converting to a boolean) is ignored. [default level: ignore]",
