  "type": "object",
  "properties": {
    "kind": {
      "enum": [
        "apitest",
        "cypress",
        "espresso",
        "imagerunner",
        "playwright",
        "puppeteer-replay",
        "testcafe",
        "xcuitest",
        "playwright-cucumberjs"
      ]
    }
  },
  "allOf": [
    {
      "if": {
        "properties": {
          "kind": {
            "const": "cypress"
          },
          "apiVersion": {
            "const": "v1alpha"
          }
        }
      },
      "then": {
        "$schema": "https://json-schema.org/draft/2020-12/schema",
        "title": "saucectl cypress runner configuration",
        "description": "Configuration file for cypress using saucectl",
        "type": "object",
        "allOf": [
          {
            "$schema": "https://json-schema.org/draft/2020-12/schema",
