                    "description": "Whether or not to do SSL key validation when making requests to the registry via https.",
                    "type": "boolean"
                  },
                  "registries": {
                    "description": "Specify all the registries you want to configure",
                    "type": "array",
                    "minimum": 0,
                    "items": {
                      "type": "object",
                      "properties": {
                        "scope": {
                          "description": "Scope for the registry entry",
