    "AccessControlPath": {
      "type": "object",
      "required": [
        "access",
        "name",
        "path"
      ],
      "properties": {
        "access": {
          "description": "Grant access",
          "allOf": [
            {
              "$ref": "#/definitions/Grant"
            }
          ]
        },
        "name": {
          "description": "Name of check (default filestem of path)",
          "type": "string"
