      "description": "The same attribute can't be specified twice.",
      "type": "boolean",
      "default": false
    },
    "attr-unsafe-chars": {
      "description": "Attribute value cant not use unsafe chars.",
      "type": "boolean",
      "default": false
    },
    "attr-value-double-quotes": {
      "description": "Attribute value must closed by double quotes.",
      "type": "boolean",
      "default": false
    },
