      "description": "Id and class value must meet some rules: underline, dash, hump.",
      "default": false,
      "enum": [false, "underline", "dash", "hump"]
    },
    "id-unique": {
      "description": "ID attributes must be unique in the document.",
      "type": "boolean",
      "default": false
    },
    "inline-script-disabled": {
      "description": "Inline script cannot be used.",
      "type": "boolean",
      "default": false
    },
    "inline-style-disabled": {
      "description": "Inline style cannot be used.",
      "type": "boolean",
      "default": false
    },
    "space-tab-mixed-disabled": {
      "description": "Spaces and tabs can not mixed in front of line.",
      "default": false,
      "enum": [false, "space", "tab"]
    },
    "spec-char-escape": {
      "description": "Special characters must be escaped.",
      "type": "boolean",
      "default": false
    },
    "src-not-empty": {
      "description": "Src of img(script,link) must set value. Empty of src will visit current page twice.",
      "type": "boolean",
      "default": false
    },
    "style-disabled": {
      "description": "Style tag can not be used.",
      "type": "boolean",
      "default": false
    },
    "tag-pair": {
      "description": "Tag must be paired.",
      "type": "boolean",
      "default": false
    },
    "tag-self-close": {
      "description": "The empty tag must closed by self.",
      "type": "boolean",
      "default": false
    },
    "tagname-lowercase": {
      "description": "Tagname must be lowercase.",
      "type": "boolean",
      "default": false
    },
    "title-require": {
      "description": "<title> must be present in <head> tag.",
      "type": "boolean",
      "default": false
    }
