{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "$id": "https://oss-review-toolkit.org/resolutions.yml",
  "title": "ORT resolutions",
  "description": "The OSS-Review-Toolkit (ORT) provides a possibility to resolve issues, rule violations and security vulnerabilities in a resolutions file. A full list of all available options can be found at https://github.com/oss-review-toolkit/ort/blob/main/docs/config-file-resolutions-yml.md.",
  "type": "object",
  "properties": {
    "issues": {
      "type": "array",
      "items": {
        "type": "object",
        "properties": {
          "message": {
            "type": "string"
          },
          "reason": {
            "$ref": "#/definitions/issueResolutionReason"
          },
          "comment": {
            "type": "string"
          }
        },
        "required": [
          "message",
          "reason"
        ]
      }
    },
    "rule_violations": {
      "type": "array",
      "items": {
        "type": "object",
        "properties": {
          "message": {
            "type": "string"
          },
          "reason": {
            "$ref": "#/definitions/ruleViolationResolutionReason"
          },
          "comment": {
            "type": "string"
          }
        },
        "required": [
          "message",
          "reason"
        ]
      }
    },
    "vulnerabilities": {
      "type": "array",
      "items": {
        "type": "object",
        "properties": {
          "id": {
            "type": "string"
          },
          "reason": {
            "$ref": "#/definitions/vulnerabilityResolutionReason"
          },
          "comment": {
            "type": "string"
          }
        },
        "required": [
          "id",
          "reason"
        ]
      }
    }
  },
  "anyOf": [
    {
      "required": [
        "issues"
      ]
    },
    {
      "required": [
        "rule_violations"
      ]
    },
    {
      "required": [
        "vulnerabilities"
      ]
    }
  ],
  "definitions": {
    "issueResolutionReason": {
      "enum": [
        "BUILD_TOOL_ISSUE",
        "CANT_FIX_ISSUE",
        "SCANNER_ISSUE"
      ]
    },
    "ruleViolationResolutionReason": {
      "enum": [
        "CANT_FIX_EXCEPTION",
        "DYNAMIC_LINKAGE_EXCEPTION",
        "EXAMPLE_OF_EXCEPTION",
        "LICENSE_ACQUIRED_EXCEPTION",
        "NOT_MODIFIED_EXCEPTION",
        "PATENT_GRANT_EXCEPTION"
      ]
    },
    "vulnerabilityResolutionReason": {
      "enum": [
        "CANT_FIX_VULNERABILITY",
        "INEFFECTIVE_VULNERABILITY",
        "INVALID_MATCH_VULNERABILITY",
        "MITIGATED_VULNERABILITY",
        "WILL_NOT_FIX_VULNERABILITY",
        "WORKAROUND_FOR_VULNERABILITY"
      ]
    }
  }
}

{
  "$id": "https://json.schemastore.org/prometheus.rules.test.json",
  "$schema": "http://json-schema.org/draft-07/schema#",
  "additionalProperties": false,
  "definitions": {
    "alert": {
      "properties": {
        "exp_annotations": {
          "$ref": "#/definitions/labels",
          "description": "Expanded annotations of the expected alert"
        },
        "exp_labels": {
          "$ref": "#/definitions/labels",
          "description": "Expanded labels and annotations of the expected alert. This also include the labels of the sample associated with the alert (same as what you see in `/alerts`, without series `__name__` and `alertname`)."
        }
      },
      "required": ["exp_labels"],
      "type": "object"
    },
    "alert_test_case": {
      "additionalProperties": false,
      "properties": {
        "alertname": {
          "description": "Name of the alert to be tested.",
          "type": "string"
        },
        "eval_time": {
          "$ref": "#/definitions/duration",
          "description": "The time elapsed from time=0s when the alerts have to be checked."
        },
        "exp_alerts": {
          "description": "List of expected alerts firing under the given alertname at the given evaluation time",
          "items": {
            "$ref": "#/definitions/alert"
          },
          "type": "array"
        }
      },
      "required": ["eval_time", "alertname"],
      "type": "object"
    },
    "duration": {
      "minLength": 1,
      "pattern": "^([0-9]+y)?([0-9]+w)?([0-9]+d)?([0-9]+h)?([0-9]+m)?([0-9]+s)?([0-9]+ms)?$",
      "type": ["string", "null"]
    },
    "label_value": {
      "type": "string"
    },
    "labels": {
      "additionalProperties": false,
      "patternProperties": {
        "^[a-zA-Z_][a-zA-Z0-9_]*$": {
          "$ref": "#/definitions/label_value"
        }
      },
      "type": ["object", "null"]
    },
    "promql_test_case": {
      "additionalProperties": false,
      "properties": {
        "eval_time": {
          "$ref": "#/definitions/duration",
          "description": "The time elapsed from time=0s when the expression has to be evaluated."
        },
        "exp_samples": {
          "description": "Expected samples at the given evaluation time.",
          "items": {
            "$ref": "#/definitions/sample"
          },
          "type": "array"
        },
        "expr": {
          "description": "PromQL expression to evaluate",
          "type": "string"
        }
      },
      "required": ["expr", "eval_time"],
      "type": "object"
    },
    "sample": {
      "properties": {
        "labels": {
          "description": "Labels of the sample in the usual series notation '<metric name>{<label name>=<label value>, ...}'",
          "type": "string"
        },
        "value": {
          "description": "Expected value of the PromQL expression.",
          "type": "number"
        }
      },
      "required": ["labels", "value"],
      "type": "object"
    },
    "series": {
      "additionalProperties": false,
      "properties": {
        "series": {
          "description": "This follows the usual series notation '<metric name>{<label name>=<label value>, ...}'.",
          "type": "string"
        },
        "values": {
          "description": "This uses expanded notation to project time series. There are also the special `_` and `stale` values to indicate missing or stale samples",
          "type": "string"
        }
      },
      "required": ["series", "values"],
      "type": "object"
    },
    "test_group": {
      "additionalProperties": false,
      "properties": {
        "alert_rule_test": {
          "description": "Unit tests for alerting rules. We only consider the alerting rules from the input files.",
          "items": {
            "$ref": "#/definitions/alert_test_case"
          },
          "type": "array"
        },
        "external_labels": {
          "$ref": "#/definitions/labels",
          "description": "External labels accessible to the alert template."
        },
        "external_url": {
          "description": "External URL accessible to the alert template. Usually set using --web.external-url.",
          "type": "string"
        },
        "input_series": {
          "description": "A list of time series",
          "items": {
            "$ref": "#/definitions/series"
          },
          "type": "array"
        },
        "interval": {
          "$ref": "#/definitions/duration",
          "description": "The time elapsed from time=0s when the alerts have to be checked."
        },
        "name": {
          "description": "Name of the test group",
          "type": "string"
        },
        "promql_expr_test": {
          "description": "Unit tests for PromQL expressions",
          "items": {
            "$ref": "#/definitions/promql_test_case"
          },
          "type": "array"
        }
      },
      "required": ["interval", "input_series"],
      "type": "object"
    }
  },
  "description": "Prometheus rules test file. See https://prometheus.io/docs/prometheus/latest/configuration/unit_testing_rules/ for details.",
  "properties": {
    "evaluation_interval": {
      "default": "1m",
      "description": "The evaluation interval for the tests. [duration] format.",
      "type": ["string", "null"]
    },
    "group_eval_order": {
      "description": "The order in which group names are listed below will be the order of evaluation of rule groups (at a given evaluation time).",
      "items": {
        "type": "string"
      },
      "type": ["array", "null"]
    },
    "rule_files": {
      "description": "List of rule files to consider for testing. Globs are supported.",
      "items": {
        "type": "string"
      },
      "type": "array"
    },
    "tests": {
      "items": {
        "$ref": "#/definitions/test_group",
        "description": "All the tests are listed here."
      },
      "type": "array"
    }
  },
  "title": "Prometheus Rules Test File",
  "type": "object"
}

{
  "$id": "https://json.schemastore.org/nodemon.json",
  "$schema": "http://json-schema.org/draft-07/schema#",
  "definitions": {
    "pathPattern": {
      "anyOf": [
        {
          "type": "string"
        },
        {
          "type": "object",
          "properties": {
            "re": {
              "type": "string"
            }
          },
          "additionalProperties": false,
          "required": ["re"],
          "description": "Regular expression"
        }
      ]
    },
    "terminationSignals": {
      "anyOf": [
        {
          "const": "SIGTERM"
        },
        {
          "const": "SIGINT"
        },
        {
          "const": "SIGQUIT"
        },
        {
          "const": "SIGKILL"
        },
        {
          "const": "SIGHUP"
        }
      ]
    },
    "variables": {
      "anyOf": [
        {
          "const": "{{pwd}}",
          "description": "The current directory"
        },
        {
          "const": "{{filename}}",
          "description": "The filename you pass to nodemon"
        }
      ]
    }
  },
  "dependencies": {
    "pollingInterval": {
      "required": ["legacyWatch"]
    },
    "nodeArgs": {
      "exec": {
        "const": "node"
      },
      "required": ["exec"]
    }
  },
  "properties": {
    "colours": {
      "default": true,
      "description": "set to false to disable color output",
      "type": "boolean"
    },
    "cwd": {
      "description": "change into <dir> before running the script",
      "type": "string"
    },
    "delay": {
      "default": 0,
      "description": "debounce restart for a number of milliseconds",
      "type": "number"
    },
    "dump": {
      "default": false,
      "description": "print full debug configuration",
      "type": "boolean"
    },
    "exec": {
      "description": "execute script with \"app\", ie. -x \"python -v\".  May use variables.",
      "examples": ["{{pwd}}/index.js --some-arg", "{{filename}}"],
      "format": "<app> <your args>",
      "type": "string"
    },
    "execMap": {
      "description": "The global config file is useful for setting up default executables",
      "type": "object"
    },
    "exitcrash": {
      "description": "Exit nodemon after crash",
      "type": "boolean"
    },
    "ext": {
      "default": "*",
      "description": "extensions to look for, ie. \"js,jade,hbs\"",
      "type": "string"
    },
    "ignore": {
      "description": "Ignore directory or file.  One entry per ignored value.  Wildcards are allowed.",
      "items": {
        "$ref": "#/definitions/pathPattern",
        "description": "Path or pattern of file or directory to ignore.  Can also use regular expressions wrapped in an object with a single property named \"re\".",
        "examples": [
          ".gitignore",
          ".vscode",
          "__tests__/*",
          "__*__/*.js",
          "*.test.js"
        ]
      },
      "type": "array"
    },
    "ignoreRoot": {
      "description": "root paths to ignore",
      "items": {
        "type": "string"
      },
      "type": "array"
    },
    "legacyWatch": {
      "default": false,
      "description": "use polling to watch for changes (typically needed when watching over a network/Docker)",
      "type": "boolean"
    },
    "noUpdateNotifier": {
      "default": false,
      "description": "opt-out of update version check",
      "type": "boolean"
    },
    "nodeArgs": {
      "description": "arguments to pass to node if exec is \"node\"",
      "type": "array"
    },
    "pollingInterval": {
      "default": 100,
      "description": "combined with legacyWatch, milliseconds to poll for (default 100)",
      "type": "number"
    },
    "quiet": {
      "default": false,
      "description": "minimise nodemon messages to start/stop only",
      "type": "boolean"
    },
    "runOnChangeOnly": {
      "default": false,
      "description": "execute script on change only, not startup",
      "type": "boolean"
    },
    "signal": {
      "$ref": "#/definitions/terminationSignals",
      "description": "use specified kill signal instead of default (ex. SIGTERM)",
      "type": "string"
    },
    "spawn": {
      "default": false,
      "description": "force nodemon to use spawn (over fork) [node only]",
      "type": "boolean"
    },
    "stdin": {
      "default": true,
      "description": "set to false to have nodemon pass stdin directly to child process",
      "type": "boolean"
    },
    "verbose": {
      "default": false,
      "description": "show detail on what is causing restarts",
      "type": "boolean"
    },
    "watch": {
      "description": "Watch directory or file.  One entry per watched value.  Wildcards are allowed.",
      "items": {
        "$ref": "#/definitions/pathPattern",
        "description": "Path or pattern of file or directory to watch.  Can also use regular expressions wrapped in an object with a single property named \"re\".",
        "examples": ["src/index.js", "src", "src/*.js", "*.js"]
      },
      "type": "array"
    }
  },
  "title": "JSON Schema for Nodemon Config",
  "type": "object"
}

{
  "$id": "https://json.schemastore.org/sponge-mixins.json",
  "$schema": "http://json-schema.org/draft-07/schema#",
  "definitions": {
    "mixin_class": {
      "type": "string",
      "description": "The dot-separated path to the mixin class relative to the specified package. The class must be annotated with @Mixin"
    },
    "injector_options": {
      "type": "object",
      "description": "Injection options",
      "properties": {
        "defaultRequire": {
          "type": "integer",
          "minimum": 0,
          "description": "Sets the default minimum of injections that must be successfully applied per injector",
          "default": 0
        },
        "defaultGroup": {
          "type": "string",
          "description": "Sets the default injector group",
          "default": "default"
        },
        "injectionPoints": {
          "type": "array",
          "description": "Registers injection points for this configuration",
          "items": {
            "type": "string"
          }
        },
        "maxShiftBy": {
          "type": "integer",
          "minimum": 0,
          "maximum": 5,
          "default": 5,
          "description": "Sets the maximum allowed number of opcodes that can be shifted in @At annotations. This is hard capped at 5"
        }
      }
    },
    "overwrite_options": {
      "type": "object",
      "description": "Overwrite options",
      "properties": {
        "conformVisibility": {
          "type": "boolean",
          "description": "Sets whether the visibility of overwritten methods should be conformed to the target class"
        },
        "requireAnnotations": {
          "type": "boolean",
          "default": true,
          "description": "Sets whether overwriting methods must explicitly be declared through @Overwrite annotations"
        }
      }
    }
  },
  "properties": {
    "parent": {
      "type": "string",
      "description": "The name of a parent configuration that options get inherited from"
    },
    "target": {
      "type": "string",
      "description": "Target selector. Either the specifies the phase directly or use \"@env(PHASE)\" separated by '&', '\\', or ' '"
    },
    "minVersion": {
      "type": "string",
      "pattern": "^(\\d{1,5})(?:\\.(\\d{1,5})(?:\\.(\\d{1,5})(?:\\.(\\d{1,5}))?)?)?(-[a-zA-Z0-9_\\-]+)?$",
      "description": "Minimum version of the mixin subsystem required for this configuration"
    },
    "compatibilityLevel": {
      "type": "string",
      "description": "Minimum compatibility level required for mixins in this set"
    },
    "required": {
      "type": "boolean",
      "description": "Determines whether mixin failures in this configuration are considered terminal and stop the game"
    },
    "priority": {
      "type": "integer",
      "description": "The priority of this configuration. Will be inherited if smaller than 0",
      "default": -1
    },
    "mixinPriority": {
      "type": "integer",
      "description": "Default mixin priority for this configuration. Will be inherited if smaller than 0",
      "default": -1
    },
    "package": {
      "type": "string",
      "description": "The target package where the mixin classes reside"
    },
    "mixins": {
      "type": "array",
      "description": "Mixin classes to load in all environments. Class names get prepended with the specified package",
      "items": {
        "$ref": "#/definitions/mixin_class"
      }
    },
    "client": {
      "type": "array",
      "description": "Mixin classes to load ONLY on client. Class names get prepended with the specified package",
      "items": {
        "$ref": "#/definitions/mixin_class"
      }
    },
    "server": {
      "type": "array",
      "description": "Mixin classes to load ONLY on server. Class names get prepended with the specified package",
      "items": {
        "$ref": "#/definitions/mixin_class"
      }
    },
    "setSourceFile": {
      "type": "boolean",
      "description": "Sets whether targets' source files will be updated to the mixin source file"
    },
    "refmap": {
      "type": "string",
      "description": "The path to the reference map resource to use for this configuration"
    },
    "verbose": {
      "type": "boolean",
      "description": "Increases log detail level from DEBUG to INFO",
      "default": false
    },
    "plugin": {
      "type": "string",
      "description": "Name of the mixin config plugin to use for this config"
    },
    "injectors": {
      "$ref": "#/definitions/injector_options"
    },
    "overwrites": {
      "$ref": "#/definitions/overwrite_options"
    }
  },
  "required": ["package"],
  "type": "object"
}

{
  "$id": "https://json.schemastore.org/paper-plugin",
  "$schema": "http://json-schema.org/draft-07/schema#",
  "additionalProperties": true,
  "definitions": {
    "plugin-name": {
      "type": "string",
      "pattern": "^[A-Za-z0-9_\\.-]+$"
    },
    "plugin-class": {
      "type": "string",
      "pattern": "^(?!io\\.papermc\\.)([a-zA-Z_$][a-zA-Z\\d_$]*\\.)*[a-zA-Z_$][a-zA-Z\\d_$]*$"
    },
    "perm-default": {
      "enum": ["true", "false", "op", "notop"]
    },
    "permission": {
      "type": "object",
      "description": "A permission for this plugin",
      "properties": {
        "default": {
          "$ref": "#/definitions/perm-default",
          "description": "Default for this permission"
        },
        "description": {
          "type": "string"
        },
        "children": {
          "oneOf": [
            {
              "type": "array",
              "items": {
                "type": "string"
              }
            },
            {
              "type": "object",
              "additionalProperties": {
                "oneOf": [
                  {
                    "type": "boolean",
                    "description": "False to not inherit the parent permission."
                  },
                  {
                    "$ref": "#/definitions/permission"
                  }
                ]
              }
            }
          ]
        }
      },
      "additionalProperties": false
    },
    "dependency": {
      "description": "A plugin dependency",
      "type": "object",
      "properties": {
        "load": {
          "description": "Where to load this dependency in relation to the plugin. Defaults to OMIT",
          "enum": ["AFTER", "BEFORE", "OMIT"]
        },
        "join-classpath": {
          "description": "Whether this dependency's classpath should be joined by the plugin. Defaults to true",
          "type": "boolean"
        },
        "required": {
          "description": "Whether this dependency is required for the plugin to load. Defaults to true",
          "type": "boolean"
        }
      },
      "additionalProperties": false
    },
    "dependency-group": {
      "type": "object",
      "additionalProperties": {
        "$ref": "#/definitions/dependency"
      }
    }
  },
  "description": "JSON schema for Paper Plugin YAML",
  "properties": {
    "name": {
      "description": "The name of the plugin",
      "$ref": "#/definitions/plugin-name"
    },
    "main": {
      "description": "The main class of the plugin",
      "examples": ["com.example.ExamplePlugin"],
      "$ref": "#/definitions/plugin-class"
    },
    "bootstrapper": {
      "description": "The main class of the custom bootstrapper for the plugin",
      "examples": ["com.example.ExamplePluginBoostrapper"],
      "$ref": "#/definitions/plugin-class"
    },
    "loader": {
      "description": "The main class of the custom plugin loader for the plugin",
      "examples": ["com.example.ExamplePluginLoader"],
      "$ref": "#/definitions/plugin-class"
    },
    "provides": {
      "description": "Satisfies dependency requirements as this plugin. When resolving dependencies, if a plugin requires a plugin in this list, this plugin will satisfy it.",
      "type": "array",
      "uniqueItems": true,
      "items": {
        "$ref": "#/definitions/plugin-name"
      }
    },
    "has-open-classloader": {
      "type": "boolean",
      "description": "Whether the plugin should have its classloader public to other paper plugins"
    },
    "version": {
      "description": "The version of the plugin",
      "type": ["string"]
    },
    "description": {
      "description": "The description of the plugin",
      "type": "string"
    },
    "authors": {
      "type": "array",
      "description": "Main authors of the plugin",
      "items": {
        "type": "string",
        "uniqueItems": true
      }
    },
    "contributors": {
      "type": "array",
      "description": "Other contributors to the plugin",
      "items": {
        "type": "string",
        "uniqueItems": true
      }
    },
    "website": {
      "type": "string",
      "description": "Plugin website"
    },
    "prefix": {
      "type": "string",
      "description": "Log prefix for this plugin. Defaults to the plugin name"
    },
    "load": {
      "enum": ["STARTUP", "POSTWORLD"],
      "description": "When to load this plugin. Defaults to POSTWORLD."
    },
    "default-perm": {
      "$ref": "#/definitions/perm-default",
      "description": "Default value for permissions. Defaults to 'op'"
    },
    "permissions": {
      "description": "Permissions for this plugin",
      "additionalProperties": {
        "$ref": "#/definitions/permission"
      }
    },
    "api-version": {
      "description": "The API version of the plugin",
      "type": "string",
      "pattern": "^1\\.\\d{2}$",
      "examples": ["1.19", "1.20"]
    },
    "dependencies": {
      "description": "Plugin dependencies.",
      "type": "object",
      "properties": {
        "bootstrap": {
          "description": "Depenencies for the plugin bootstrapper",
          "$ref": "#/definitions/dependency-group"
        },
        "server": {
          "description": "Depenencies for the server",
          "$ref": "#/definitions/dependency-group"
        }
      },
      "additionalProperties": false
    }
  },
  "required": ["name", "version", "main", "api-version"],
  "title": "Paper paper-plugin.yml",
  "type": "object"
}

{
  "$id": "https://json.schemastore.org/drupal-permissions.json",
  "$schema": "http://json-schema.org/draft-07/schema#",
  "additionalProperties": {
    "title": "Permission definition",
    "type": "object",
    "required": ["title"],
    "properties": {
      "title": {
        "title": "The human-readable name of the permission",
        "type": "string"
      },
      "description": {
        "title": "A description of what the permission does",
        "type": "string"
      },
      "restrict access": {
        "title": "Restrict access to this permission to trusted users",
        "description": "This should be used for permissions that have inherent security risks across a variety of potential use cases (for example, the \"administer filters\" and \"bypass node access\" permissions provided by Drupal core).",
        "type": "boolean"
      }
    },
    "additionalProperties": false
  },
  "properties": {
    "permission_callbacks": {
      "title": "List of permission callbacks",
      "type": "array",
      "items": {
        "title": "A callback that return array of permissions",
        "type": "string"
      },
      "uniqueItems": true
    }
  },
  "title": "JSON schema for Drupal permissions file",
  "type": "object"
}

{
  "$id": "https://json.schemastore.org/vim-addon-info",
  "$schema": "http://json-schema.org/draft-07/schema#",
  "definitions": {
    "url": {
      "type": "string",
      "format": "uri",
      "examples": ["git://github.com/tpope/vim-surround"]
    },
    "repoType": {
      "enum": ["hg", "git", "svn", "bzr"]
    },
    "selfRepository": {
      "description": "Info for the plugin itself. Describes where the canonical copy of the plugin can be fetched from.",
      "type": "object",
      "properties": {
        "type": {
          "$ref": "#/definitions/repoType"
        },
        "url": {
          "$ref": "#/definitions/url"
        },
        "deprecated": {
          "description": "For a deprecated plugin, a deprecation message to be shown to any user who installs the plugin.",
          "type": "string"
        }
      },
      "dependencies": {
        "url": ["type"],
        "type": ["url"]
      }
    },
    "otherRepository": {
      "description": "Info about a plugin/repository outside this one.",
      "type": "object",
      "anyOf": [
        {
          "$comment": "Empty repository info. Used to declare plugin with the given name is required without specifying any explicit details about how to fetch it (e.g., if name can be looked up in a predefined package index).",
          "additionalProperties": false
        },
        {
          "$comment": "Repository with empty type and url pointing to local path.",
          "properties": {
            "type": {
              "enum": ["", "archive"]
            },
            "url": {
              "$ref": "#/definitions/url"
            },
            "vim_script_nr": {
              "description": "Script ID number of the target plugin on www.vim.org, if any.",
              "type": "number",
              "examples": [31, 1075]
            },
            "script-type": {
              "enum": [
                "color scheme",
                "ftplugin",
                "game",
                "indent",
                "syntax",
                "utility",
                "patch"
              ]
            }
          }
        },
        {
          "$comment": "Explicit remote repository.",
          "properties": {
            "type": {
              "$ref": "#/definitions/repoType"
            },
            "url": {
              "$ref": "#/definitions/url"
            }
          },
          "required": ["type", "url"]
        }
      ],
      "properties": {
        "homepage": {
          "description": "Primary homepage of the plugin.",
          "type": "string",
          "format": "uri"
        },
        "addon-info": {
          "$comment": "Addon information for the other plugin in case it does not supply its own addon-info file.",
          "$ref": "#"
        }
      }
    }
  },
  "properties": {
    "name": {
      "description": "The name of the plugin. Used by plugin managers and some introspection tools. Generally corresponds to the name of the repository but without \"vim\" prefix/suffix.",
      "type": "string",
      "examples": ["surround.vim", "nerdtree", "maktaba"]
    },
    "version": {
      "description": "Dotted version number of the plugin, generally in semantic versioning scheme.",
      "type": "string",
      "examples": ["0.0.1", "2.0"],
      "default": "0.0.1"
    },
    "description": {
      "description": "Short description of the plugin and what it does (a sentence or two)",
      "type": "string"
    },
    "homepage": {
      "description": "Primary homepage of the plugin.",
      "type": "string",
      "format": "uri"
    },
    "author": {
      "description": "Name of the person or organization that created the plugin",
      "type": "string",
      "examples": ["Priya Exampleton", "Example Industries"]
    },
    "maintainer": {
      "description": "Name of the person who maintains the plugin",
      "type": "string",
      "examples": ["Priya Exampleton"]
    },
    "repository": {
      "$ref": "#/definitions/selfRepository"
    },
    "dependencies": {
      "description": "Plugins that are strictly required for the plugin to work, where keys are plugin names and values may describe where plugins can be fetched from.",
      "type": "object",
      "additionalProperties": {
        "$ref": "#/definitions/otherRepository"
      }
    }
  },
  "title": "JSON schema for vim plugin addon-info.json metadata files",
  "type": "object"
}

{
  "$id": "https://aka.ms/winget-manifest.locale.1.0.0.schema.json",
  "$schema": "http://json-schema.org/draft-07/schema#",
  "definitions": {
    "Url": {
      "type": ["string", "null"],
      "pattern": "^([Hh][Tt][Tt][Pp][Ss]?)://.+$",
      "maxLength": 2000,
      "description": "Optional Url type"
    },
    "Tag": {
      "type": ["string", "null"],
      "minLength": 1,
      "maxLength": 40,
      "description": "Package moniker or tag"
    }
  },
  "description": "A representation of a multiple-file manifest representing app metadata in other locale in the OWC. v1.0.0",
  "properties": {
    "PackageIdentifier": {
      "type": "string",
      "pattern": "^[^\\.\\s\\\\/:\\*\\?\"<>\\|\\x01-\\x1f]{1,32}(\\.[^\\.\\s\\\\/:\\*\\?\"<>\\|\\x01-\\x1f]{1,32}){1,3}$",
      "maxLength": 128,
      "description": "The package unique identifier"
    },
    "PackageVersion": {
      "type": "string",
      "pattern": "^[^\\\\/:\\*\\?\"<>\\|\\x01-\\x1f]+$",
      "maxLength": 128,
      "description": "The package version"
    },
    "PackageLocale": {
      "type": "string",
      "pattern": "^([a-zA-Z]{2}|[iI]-[a-zA-Z]+|[xX]-[a-zA-Z]{1,8})(-[a-zA-Z]{1,8})*$",
      "maxLength": 20,
      "description": "The package meta-data locale"
    },
    "Publisher": {
      "type": ["string", "null"],
      "minLength": 2,
      "maxLength": 256,
      "description": "The publisher name"
    },
    "PublisherUrl": {
      "$ref": "#/definitions/Url",
      "description": "The publisher home page"
    },
    "PublisherSupportUrl": {
      "$ref": "#/definitions/Url",
      "description": "The publisher support page"
    },
    "PrivacyUrl": {
      "$ref": "#/definitions/Url",
      "description": "The publisher privacy page or the package privacy page"
    },
    "Author": {
      "type": ["string", "null"],
      "minLength": 2,
      "maxLength": 256,
      "description": "The package author"
    },
    "PackageName": {
      "type": ["string", "null"],
      "minLength": 2,
      "maxLength": 256,
      "description": "The package name"
    },
    "PackageUrl": {
      "$ref": "#/definitions/Url",
      "description": "The package home page"
    },
    "License": {
      "type": ["string", "null"],
      "minLength": 3,
      "maxLength": 512,
      "description": "The package license"
    },
    "LicenseUrl": {
      "$ref": "#/definitions/Url",
      "description": "The license page"
    },
    "Copyright": {
      "type": ["string", "null"],
      "minLength": 3,
      "maxLength": 512,
      "description": "The package copyright"
    },
    "CopyrightUrl": {
      "$ref": "#/definitions/Url",
      "description": "The package copyright page"
    },
    "ShortDescription": {
      "type": ["string", "null"],
      "minLength": 3,
      "maxLength": 256,
      "description": "The short package description"
    },
    "Description": {
      "type": ["string", "null"],
      "minLength": 3,
      "maxLength": 10000,
      "description": "The full package description"
    },
    "Moniker": {
      "$ref": "#/definitions/Tag",
      "description": "The most common package term"
    },
    "Tags": {
      "type": ["array", "null"],
      "items": {
        "$ref": "#/definitions/Tag"
      },
      "maxItems": 16,
      "uniqueItems": true,
      "description": "List of additional package search terms"
    },
    "ManifestType": {
      "type": "string",
      "default": "locale",
      "const": "locale",
      "description": "The manifest type"
    },
    "ManifestVersion": {
      "type": "string",
      "default": "1.0.0",
      "pattern": "^(0|[1-9][0-9]{0,3}|[1-5][0-9]{4}|6[0-4][0-9]{3}|65[0-4][0-9]{2}|655[0-2][0-9]|6553[0-5])(\\.(0|[1-9][0-9]{0,3}|[1-5][0-9]{4}|6[0-4][0-9]{3}|65[0-4][0-9]{2}|655[0-2][0-9]|6553[0-5])){2}$",
      "description": "The manifest syntax version"
    }
  },
  "required": [
    "PackageIdentifier",
    "PackageVersion",
    "PackageLocale",
    "ManifestType",
    "ManifestVersion"
  ],
  "type": "object"
}

{
  "$id": "https://raw.githubusercontent.com/ansible/ansible-lint/main/src/ansiblelint/schemas/vars.json",
  "$schema": "http://json-schema.org/draft-07/schema",
  "anyOf": [
    {
      "additionalProperties": false,
      "patternProperties": {
        "^(?!(False|None|True|and|any_errors_fatal|as|assert|async|await|become|become_exe|become_flags|become_method|become_user|break|check_mode|class|collections|connection|continue|debugger|def|del|diff|elif|else|environment|except|fact_path|finally|for|force_handlers|from|gather_facts|gather_subset|gather_timeout|global|handlers|hosts|if|ignore_errors|ignore_unreachable|import|in|is|lambda|max_fail_percentage|module_defaults|name|no_log|nonlocal|not|or|order|pass|port|post_tasks|pre_tasks|raise|remote_user|return|roles|run_once|serial|strategy|tags|tasks|throttle|timeout|try|vars|vars_files|vars_prompt|while|with|yield)$)[a-zA-Z_][\\w]*$": {}
      },
      "type": "object"
    },
    {
      "pattern": "^\\$ANSIBLE_VAULT;",
      "type": "string"
    },
    {
      "type": "null"
    }
  ],
  "examples": [
    "playbooks/vars/*.yml",
    "vars/*.yml",
    "defaults/*.yml",
    "host_vars/*.yml",
    "group_vars/*.yml"
  ],
  "markdownDescription": "See [Using Variables](https://docs.ansible.com/ansible/latest/playbook_guide/playbooks_variables.html)",
  "title": "Ansible Vars Schema"
}

{
  "$comment": "https://developer.chrome.com/docs/extensions/mv3/i18n-messages/",
  "$id": "https://json.schemastore.org/chrome-extension-locales-messages.json",
  "$schema": "http://json-schema.org/draft-07/schema#",
  "additionalProperties": false,
  "patternProperties": {
    "^(?!@@)[\\w@]+$": {
      "properties": {
        "message": {
          "description": "The translated message, in the form of a string that can contain placeholders. Use `$_placeholder_name_$` (case insensitive) to refer to a particular placeholder. For example, you can refer to a placeholder named \"our_site\" as `$our_site$`, `$OUR_SITE$`, or `$oUR_sITe$`.\nTo put a dollar sign (`$`) into the string, use `$$`.\nAlthough placeholders such as `$USER$` are the preferred way of referring to substitution strings (strings specified using the substitutions parameter of i18n.getMessage) you can also refer to substitution strings directly within the message.",
          "examples": [
            "What's your name?",
            "Hello, $USER$",
            "Goodbye, $USER$. Come back to $OUR_SITE$ soon!",
            "Amount (in $$)",
            "Params: $1, $2, $3"
          ],
          "type": "string",
          "title": "message"
        },
        "description": {
          "description": "Optional. A description of the message, intended to give context or details to help the translator make the best possible translation.",
          "examples": [
            "Ask for the user's name",
            "Greet the user",
            "Say goodbye to the user"
          ],
          "type": "string",
          "title": "description"
        },
        "placeholders": {
          "description": "Optional. Defines one or more substrings to be used within the message.\nEach placeholder has a name, a \"content\" item, and an optional \"example\" item. A placeholder's name is case-insensitive and can contain the same characters as a message name.\n",
          "patternProperties": {
            "^[\\w@]+$": {
              "properties": {
                "content": {
                  "description": "The \"content\" item's value is a string that can refer to substitution strings, which are specified using the i18n.getMessage method's substitutions parameter. The value of a \"content\" item is typically something like \"Example.com\" or \"$1\". If you refer to a substitution string that doesn't exist, you get an empty string. The following table shows how `$_n_` strings correspond to strings specified by the substitutions parameter.",
                  "type": "string",
                  "title": "content"
                },
                "example": {
                  "description": "The \"example\" item (optional, but highly recommended) helps translators by showing how the content appears to the end user. For example, a placeholder for a dollar amount should have an example like `\"$23.45\"`.",
                  "type": "string",
                  "title": "example"
                }
              },
              "required": ["content"],
              "type": "object"
            }
          },
          "type": "object",
          "title": "placeholders"
        }
      },
      "required": ["message"],
      "type": "object"
    }
  },
  "type": "object"
}

{
