            "type": "string"
          }
        },
        "skip": {
          "type": "array",
          "description": "A list of items to not create, copy, replace, or remove in target file",
          "items": {
            "type": "string"
          }
        },
        "skipIfNotSameFileName": {
          "type": "array",
          "items": {
            "type": "string"
          }
        }
      }
    },
    "mergeYaml": {
      "description": "Merge yaml file with yq command line tool pattern matching",
      "required": ["type", "path"],
      "additionalProperties": false,
